def values(self, *keys):
    """
    Return the values of the record, optionally filtering to include only
    certain values by index or key.

    :param keys: indexes or keys of the items to include; if none are provided,
                 all values will be included
    :return: list of values
    """
    # Helper to obtain an ordered list of (idx, key, value)
    if hasattr(self, "items"):
        items = list(self.items())
    else:
        # Assume an iterable of (key, value) tuples
        items = [(i, k, v) for i, (k, v) in enumerate(self)]

    # If no filters, return all values
    if not keys:
        return [v for _, _, v in items]

    result = []
    for key in keys:
        if isinstance(key, int):
            # treat as an index
            if 0 <= key < len(items):
                result.append(items[key][2])
        else:
            # treat as a key lookup
            if key in dict(items):
                result.append(dict(items)[key])
    return result

