def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Gather names from class definitions, slots, and instance attributes.
    names = set()

    # Helper to collect from a single class
    def collect_cls(c):
        # Class dictionaries
        for name, val in c.__dict__.items():
            if not name.startswith('_') and not callable(val):
                names.add(name)
        # Slots
        slots = getattr(c, '__slots__', [])
        if isinstance(slots, str):
            slots = [slots]
        for slot in slots:
            if not slot.startswith('_'):
                names.add(slot)

    # If all=True, walk the MRO, otherwise only the current class
    classes = self.__class__.mro() if all else (self.__class__,)
    for cl in classes:
        collect_cls(cl)

    # Instance attributes
    for name in self.__dict__:
        if not name.startswith('_'):
            names.add(name)

    return sorted(names)

