def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    for arg in sequence:
        if arg is None:
            continue

        # Keep individual interfaces, declarations, and implements specs as
        # they are.  These are the minimal items that should appear in the
        # flattened list.
        if isinstance(arg, (Declaration, ImplementsSpec, Interface)):
            output.append(arg)

        # Expand tuples/lists/sets recursively.
        elif isinstance(arg, (tuple, list, set)):
            _normalizeargs(arg, output)

        # For any non‑recognized type, add it directly.
        else:
            output.append(arg)

    return output

