def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate.

    The method expects that error indices are stored in an attribute
    ``error_indices`` on the instance.  This attribute should be a
    dictionary that maps coordinate names to an iterable (list,
    tuple, set, etc.) of indices where errors were detected.  If the
    attribute does not exist, or the coordinate is not present in the
    dictionary, an empty tuple is returned.
    """

    # The common case: a dict called ``error_indices`` exists on the instance.
    if hasattr(self, "error_indices") and isinstance(self.error_indices, dict):
        return tuple(self.error_indices.get(coord_name, ()))

    # Fallback: maybe the class exposes a custom method to fetch indices.
    # This is optional and keeps the implementation flexible.
    if hasattr(self, "get_error_indices_for"):
        try:
            result = self.get_error_indices_for(coord_name)
            return tuple(result) if result is not None else ()
        except Exception:
            # If the custom method fails, fall back to an empty result
            pass

    # In all other cases, return an empty tuple to indicate no indices found.
    return ()

