    for key, val in d1.items():
        if key not in d2:
            result[key] = val
            continue

        val2 = d2[key]
        if isinstance(val, dict) and isinstance(val2, dict) and level != 0:
            new_level = level-1 if level > 0 else -1
            sub = difference(val, val2, new_level)
            if sub:
                result[key] = sub
        else:
            if val != val2:
                result[key] = val
    return result

