def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Guard against missing spec or manifest
    if not hasattr(app, "spec") or not hasattr(app.spec, "manifest"):
        return

    for idx, res in enumerate(app.spec.manifest):
        # Skip if the resource already has an observer schema
        if res.get("observer_schema"):
            continue

        # Extract useful metadata
        meta = res.get("metadata", {})
        name = meta.get("name")
        namespace = meta.get("namespace", "default")
        kind = res.get("kind")
        api_version = res.get("apiVersion")

        # Build a minimal observer schema that expects a single resource and a simple lookup
        default_schema = {
            "grok": {
                "resources": [
                    {
                        "name": name,
                        "apiVersion": api_version,
                        "kind": kind,
                        "lookupKey": f"{namespace}/{name}",
                    }
                ],
                "lookup": [
                    {
                        "namespace": namespace,
                        "name": name,
                    }
                ],
            }
        }

        # Store the generated default observer schema back into the resource
        res["observer_schema"] = default_schema

    # Return the modified application object for convenience
    return app

