def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os

    # Allow a PyFS root object (has a .path attribute) or a string path
    if isinstance(path, str):
        root = path
    elif hasattr(path, "path") and isinstance(path.path, str):
        root = path.path
    else:
        return False

    # The root must be an existing directory
    if not os.path.isdir(root):
        return False

    # Check for the mandatory .ocfl_version file
    ocf_version_file = os.path.join(root, ".ocfl_version")
    if not os.path.isfile(ocf_version_file):
        return False
    try:
        with open(ocf_version_file, "r") as f:
            version = f.read().strip()
    except Exception:
        return False
    # A simple check that the version string looks like an OCFL spec version
    if not (version.startswith("ocfl_") or version.startswith("OCFL/")):
        return False

    # The objects directory must exist
    objects_dir = os.path.join(root, "objects")
    if not os.path.isdir(objects_dir):
        return False

    # Every object directory should contain at least one version directory
    object_ids = [
        d for d in os.listdir(objects_dir)
        if os.path.isdir(os.path.join(objects_dir, d))
    ]
    if not object_ids:
        return False

    for obj_id in object_ids:
        obj_path = os.path.join(objects_dir, obj_id)
        versions_path = os.path.join(obj_path, "versions")
        if not os.path.isdir(versions_path):
            return False

        version_ids = [
            v for v in os.listdir(versions_path)
            if os.path.isdir(os.path.join(versions_path, v))
        ]
        if not version_ids:
            return False

        # Check that the first version contains an 'artifacts' directory
        first_version = os.path.join(versions_path, version_ids[0])
        artifacts_dir = os.path.join(first_version, "artifacts")
        if not os.path.isdir(artifacts_dir):
            return False

    # All basic checks passed: consider the container valid
    return True

