def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Create a set of all digests listed in the manifest
    digests_in_manifest = set()
    for file_name, meta in manifest_files.items():
        # Manifest entries may store digests under various keys; try common ones
        for key in ('digests', 'checksums', 'hashes'):
            digests = meta.get(key)
            if digests:
                if isinstance(digests, (list, tuple, set)):
                    digests_in_manifest.update(digests)
                else:
                    digests_in_manifest.add(digests)

    # All digests that the calling code claims are used must appear in the manifest
    for d in digests_used:
        if d not in digests_in_manifest:
            raise ValueError(
                f"Digest {d!r} is used but not found in the manifest files."
            )

    # All digests listed in the manifest should be in the set of used digests
    for d in digests_in_manifest:
        if d not in digests_used:
            raise ValueError(
                f"Digest {d!r} appears in the manifest but is not marked as used."
            )

    return True

