def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic sanity check
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary mapping versions to path maps")

    # Fetch the map for the requested version
    path_map = inventory.get(version)
    if path_map is None:
        raise KeyError(f"Version {version!r} not found in inventory")

    # Create a copy where each value is a set (to avoid accidental mutation)
    result = {}
    for logical_path, files in path_map.items():
        if isinstance(files, set):
            result[logical_path] = files.copy()
        else:
            # Accept any iterable of files
            result[logical_path] = set(files)

    return result

