def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    lines = []
    prefix = '    ' * indent
    # build a simple representation of the object's class and non-child attributes
    try:
        attrs = {k: v for k, v in vars(self).items() if k not in ('children', '_children')}
    except Exception:
        attrs = {}
    line = f"{prefix}{self.__class__.__name__}"
    if attrs:
