def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        from importlib import metadata
    except Exception:
        # Fallback to default when importlib.metadata is unavailable
        return {"default": "0.0.0"}
    versions = {}
    try:
        for dist in metadata.distributions():
            name = dist.metadata.get("Name")
            if name:
                versions[name] = dist.version
    except Exception:
        # If anything goes wrong while iterating distributions,
        # fall back to minimal default.
        return {"default": "0.0.0"}
    if versions:
        return versions
    # No distributions found; return a default entry
    return {"default": "0.0.0"}

