def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0

        # Use a stack for a depth‑first traversal of the hierarchy.
        stack = [self]
        while stack:
            element = stack.pop()
            num_objects += 1
            element_is_valid = True

            if validate_objects and hasattr(element, "validate") and callable(element.validate):
                try:
                    result = element.validate()
                    if not isinstance(result, bool):
                        # If validate() returns something else we consider it as success
                        result = True
                    element_is_valid = result
                except Exception as exc:
                    element_is_valid = False
                    if show_warnings:
                        print(f"Warning: validation of {element} raised {exc!r}")

            if check_digests and hasattr(element, "digest"):
                try:
                    # If a method exists that produces the current digest we use it,
                    # otherwise we assume element.digest already represents the current value.
                    current_digest = (
                        element.generate_digest()
                        if hasattr(element, "generate_digest") and callable(element.generate_digest)
                        else element.digest
                    )
                    if element.digest != current_digest:
                        element_is_valid = False
                        if show_warnings:
                            print(f"Warning: digest mismatch for {element}")
                except Exception as exc:
                    element_is_valid = False
                    if show_warnings:
                        print(f"Warning: digest check for {element} raised {exc!r}")

            if element_is_valid:
                good_objects += 1

            # Add child elements to the stack (if any)
            try:
                for child in element:
                    stack.append(child)
            except TypeError:
                # element is not iterable; no children to add
                pass

        return num_objects, good_objects

