def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # A dictionary mapping file name to a list of (version, root_digest, current_digest)
    self.different_digests = {}

    # Ensure we have a root inventory to compare against
    root_inventory = None

    for idx, vdir in enumerate(version_dirs):
        # Path to the inventory file for this version
        inventory_path = os.path.join(self.base_dir, vdir, 'inventory.xml')

        # 1. Validate that the inventory file exists
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Missing inventory file in version directory '{vdir}'")

        # 2. Load the inventory into a dictionary {filename: digest}
        try:
            root = ET.parse(inventory_path).getroot()
        except Exception as exc:
            raise ValueError(f"Could not parse inventory.xml in '{vdir}': {exc}")

        inventory_digests = {}
        for file_elem in root.findall('.//file'):
            name = file_elem.get('name')
            digest = file_elem.get('digest')
            if name is None or digest is None:
                continue  # ignore malformed entries
            inventory_digests[name] = digest

        # 3. For the first version, establish the root inventory
        if idx == 0:
            root_inventory = inventory_digests
        else:
            # Compare against the root inventory for all files
            for fname, cur_digest in inventory_digests.items():
                root_digest = root_inventory.get(fname)
                # If the file is absent in the root inventory, skip comparison
                if root_digest is None:
                    continue
                if cur_digest != root_digest:
                    self.different_digests.setdefault(fname, []).append(
                        (vdir, root_digest, cur_digest)
                    )

        # 4. Ensure earlier inventories are present (implicit by iteration order)
        # Nothing else needed; if we reach this point all prior iterations succeeded.

    # Return the mapping of differing digests for downstream checks
    return self.different_digests

