def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if bug_ids is None:
        return
    # Convert the bug_ids into a comma‑separated string
    if isinstance(bug_ids, (list, tuple)):
        ids_str = ",".join(str(b) for b in bug_ids)
    elif isinstance(bug_ids, str):
        ids_str = bug_ids
    else:
        ids_str = str(bug_ids)
    # Combine with any existing ids in the params, if present
    if "ids" in params:
        existing = params["ids"]
        if isinstance(existing, (list, tuple)):
            existing_str = ",".join(str(e) for e in existing)
        else:
            existing_str = str(existing)
        combined = ",".join([existing_str, ids_str]) if existing_str else ids_str
        params["ids"] = combined
    else:
        params["ids"] = ids_str
    # No value is returned; the params dictionary is modified in place.

