def split(s, platform='this'):
    import os, re, shlex
    if platform == 'this':
        platform = 0 if os.name == 'nt' else 1
    if platform == 1:
        # POSIX-compatible split
        return shlex.split(s, posix=True)
    else:
        # Windows (cmd.exe) style split – a simplified regex-based approach
        # Matches either a quoted string or a non-whitespace sequence.
        pattern = r'''(?:(?:"([^"]*)")|(\S+))'''
        tokens = re.findall(pattern, s)
        result = []
        for quoted, unquoted in tokens:
            if quoted:
                result.append(quoted)
            else:
                result.append(unquoted)
        return result

