def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and parse each configuration file.
    Return a tuple of:
        1. dict mapping configuration filename to parsed configuration (as a dict)
        2. sequence of logging.LogRecord instances containing any parse errors.
    """
    import json, os, re
    configs = {}
    error_records = []

    def _resolve_env_in_dict(d):
        if isinstance(d, dict):
            return {
                k: _resolve_env_in_dict(v)
                for k, v in d.items()
            }
        elif isinstance(d, list):
            return [_resolve_env_in_dict(e) for e in d]
        elif isinstance(d, str):
            # Expand environment variables like $VAR or ${VAR}
            return os.path.expandvars(d)
        else:
            return d

    def _merge_dict(dest, src):
        for k, v in src.items():
            if (
                k in dest
                and isinstance(dest[k], dict)
                and isinstance(v, dict)
            ):
                _merge_dict(dest[k], v)
            else:
                dest[k] = v

    for filename in config_filenames:
        try:
            with open(filename, "r", encoding="utf-8") as f:
                parsed = json.load(f)
        except Exception as exc:
            msg = f"Error parsing configuration file '{filename}': {exc}"
            error_records.append(
                logging.LogRecord(
                    name="config_loader",
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=msg,
                    args=(),
                    exc_info=None,
                )
            )
            continue

        if resolve_env:
            parsed = _resolve_env_in_dict(parsed)

        if overrides:
            _merge_dict(parsed, overrides)

        configs[filename] = parsed

    return configs, error_records

