def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a sequence type, return it unchanged.
    if isinstance(seq, (list, tuple, str, bytes, bytearray)):
        return seq, type(seq)

    # Handle file-like objects that provide a read() method.
    if hasattr(seq, "read") and callable(seq.read):
        if bufsize is not None:
            # Read a chunk and then the remainder (to handle large files)
            data = seq.read(bufsize)
            rest = seq.read()
            if rest:
                data = data + rest
        else:
            data = seq.read()
        return data, type(data)

    # Fall back to converting the iterable into a list.
    try:
        seq2 = list(seq)
        return seq2, list
    except TypeError:
        # ``seq`` is not iterable; wrap it in a single‑item sequence.
        return [seq], list

