def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """

    # Helper to compute the integral of the histogram
    def _compute_scale():
        # Try common histogram attributes
        for attr in ("values", "data", "count"):
            if hasattr(self, attr):
                data = getattr(self, attr)
                try:
                    # NumPy array or iterable
                    return float(data.sum()) if hasattr(data, "sum") else float(sum(data))
                except Exception:
                    continue
        # Fallback: iterate over histogram's own __iter__
        try:
            return float(sum(self))
        except Exception:
            raise ValueError("Unable to compute scale: no suitable data found")

    # Get current scale
    if other is None:
        if not hasattr(self, "_scale") or recompute or self._scale is None:
            self._scale = _compute_scale()
        return self._scale

    # Rescale to given value
    try:
        target_scale = float(other)
    except Exception:
        raise TypeError("other must be a numeric value representing the target scale")

    current_scale = self.scale(recompute=recompute)

    if target_scale == 0:
        raise LenaValueError("Cannot rescale histogram: target scale is zero")
    if current_scale == 0:
        raise LenaValueError("Cannot rescale histogram: current scale is zero")

    factor = target_scale / current_scale

    # Apply scaling factor to the underlying data
    for attr in ("values", "data", "count"):
        if hasattr(self, attr):
            data = getattr(self, attr)
            try:
                if hasattr(data, "__mul__"):
                    # Update in place if possible
                    if hasattr(data, "__imul__"):
                        data *= factor
                    else:
                        setattr(self, attr, data * factor)
                break
            except Exception:
                continue
    else:
        # Fallback: try to iterate and scale if iterable
        try:
            new_data = [v * factor for v in self]
            # Attempt to update internal state if possible
            if hasattr(self, "_data"):
                self._data = new_data
            else:
                # Might not be able to replace internal representation
                pass
        except Exception:
            pass

    # Store the new scale
    self._scale = target_scale
    return target_scale

