        if abstract_methods:
            missing = [m for m in abstract_methods if not hasattr(candidate_cls, m)]
            if missing:
                return False
            return True

    # If iface provides a collection of required attribute names
    if hasattr(iface, "required_attrs"):
        required = getattr(iface, "required_attrs")
        if not isinstance(required, (list, tuple, set)):
            required = list(required)
        missing = [name for name in required if not hasattr(candidate_cls, name)]
        if missing:
            return False
        return True

    # If iface is a callable that returns required names
    if callable(iface):
        try:
            required = iface()
            if not isinstance(required, (list, tuple, set)):
                required = list(required)
        except Exception:
            return False
        missing = [name for name in required if not hasattr(candidate_cls, name)]
        if missing:
            return False
        return True

    # Fallback: if tentative mode, just check for any public attribute
    if tentative:
        public_attrs = [attr for attr in dir(candidate_cls) if not attr.startswith('_')]
        return bool(public_attrs)

    # Could not verify
    return False

