def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is provided, use it after checking compatibility
    if explicit_mc is not None:
        for b in bases:
            base_mc = type(b)
            if not issubclass(explicit_mc, base_mc):
                raise TypeError(
                    f"Explicit metaclass {explicit_mc!r} is not a subclass of {base_mc!r}"
                )
        return explicit_mc

    # Gather the metaclasses of all bases (excluding the plain 'type')
    metaclasses = [type(b) for b in bases]
    candidates = [mc for mc in metaclasses if mc is not type]

    # If none of the bases specify a custom metaclass, the default is 'type'
    if not candidates:
        return type

    # Resolve conflicts between metaclasses by finding the most derived common superclass
    final = candidates[0]
    for mc in candidates[1:]:
        if issubclass(final, mc):
            final = mc
        elif not issubclass(mc, final):
            raise TypeError(
                f"Metaclass conflict: {final!r} and {mc!r} are incompatible"
            )
    return final

