            year, month, day = map(int, date_part.split('-'))
        else:
            year = int(date_part[:4])
            month = int(date_part[4:6])
            day = int(date_part[6:])
    elif re.fullmatch(r'\d{4}[-]?W\d{2}', date_part):
        year = int(date_part[:4])
        week = int(date_part[5:7])
        wday = 1  # lowest value
    elif re.fullmatch(r'\d{4}[-]?W\d{2}[-]?\d', date_part):
