    tzinfo = None
    if tz_str:
        if tz_str.lower() == 'z':
            tzinfo = tzutc()
        else:
            sign = 1 if tz_str[0] == '+' else -1
            hhmm = tz_str[1:]
            if ':' in hhmm:
