            offset = sign * (int(hh) * 3600 + int(mm) * 60)
            if offset == 0:
                tzinfo = tzutc()
            else:
                tzinfo = tzoffset(tz_str, offset)

    # Return datetime
    return datetime(parsed_date.year, parsed_date.month, parsed_date.day,
