def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Helper to remove namespace from tag
    def _strip_ns(tag: str) -> str:
        return tag.split("}")[-1] if "}" in tag else tag

    # Attempt JSON parsing first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            # Ensure expected JSON structure
            if "subject" in data:
                # Normalise link objects
                links = data.get("links", [])
                normalized_links = []
                for link in (links or []):
                    if isinstance(link, dict):
                        normalized_links.append({k: v for k, v in link.items()})
                data["links"] = normalized_links
                return data
    except json.JSONDecodeError:
        pass

    # If JSON parsing failed, try XRD (XML)
    try:
        root = ET.fromstring(document)

        # Extract subject
        subject_el = root.find(".//{*}subject")
        subject = subject_el.text.strip() if subject_el is not None and subject_el.text else None

        # Extract links
        links = []
        for link_el in root.findall(".//{*}Link"):
            if link_el.tag is None:
                continue
            link_attrs = {}
            # Consider both attributes and child elements
            for k, v in link_el.attrib.items():
                link_attrs[k] = v
            for child in link_el:
                tag = _strip_ns(child.tag)
                if child.text is not None:
                    link_attrs[tag] = child.text.strip()
            links.append(link_attrs)

        # Gather other top-level elements (Id, etc.)
        extras = {}
        for elem in root:
            tag = _strip_ns(elem.tag)
            if tag in {"subject", "link"}:
                continue
            if elem.text is not None:
                extras[tag] = elem.text.strip()

        result = {}
        if subject:
            result["subject"] = subject
        if links:
            result["links"] = links
        if extras:
            result.update(extras)
        return result
    except ET.ParseError:
        pass

    # If neither format could be parsed, return empty dict
    return {}

