        required = []
        for opt in options_spec:
            req = opt.get('required_when')
            if not req:
                continue
            if isinstance(req, bool):
                if req:
                    required.append(opt.get('name'))
            elif callable(req):
                try:
                    if req(command_name=command_name, args=args):
                        required.append(opt.get('name'))
                except Exception:
                    pass
            else:
                # assume string expression; evaluate in context of command_name and args
                try:
                    ctx = {'command_name': command_name, 'args': args}
                    if eval(req, {}, ctx):
                        required.append(opt.get('name'))
                except Exception:
                    continue
        return required

