def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.

    The method expects ``args`` to be an iterable of objects that
    expose a ``value`` attribute (the data to be validated) and an
    optional ``max_length`` attribute describing the maximum allowed
    length.  If an argument has no ``max_length`` specified the
    validator simply skips it.  The validator raises a
    :class:`ValueError` if the length of the value exceeds the
    maximum.
    """
    if not hasattr(args, '__iter__'):
        raise TypeError("args must be an iterable of argument objects")
    for arg in args:
        # Skip objects without the required attributes
        if not hasattr(arg, "value") or not hasattr(arg, "max_length"):
            continue
        # Get the value to be checked
        try:
            value = arg.value
        except Exception as exc:
            raise ValueError(f"Unable to access value of argument {arg!r}") from exc
        # Only sequences may have a meaningful length
        try:
            length = len(value)
        except TypeError:
            continue
        max_len = getattr(arg, "max_length", None)
        if max_len is None:
            continue
        if length > max_len:
            raise ValueError(
                f"Argument {getattr(arg, 'name', str(arg))} length "
                f"{length} exceeds maximum of {max_len}"
            )

