def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Expect a mapping of argument name to list of allowed choices.
    choices_map = getattr(self, 'CHOICES', None) or getattr(self, 'choices', None)
    if not choices_map:
