def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # initialise result dictionaries
    control_args = {}
    nested_args = {}

    # if no args supplied, simply return empty dicts
    if not args:
        return control_args, nested_args

    # determine iterable of key/value pairs
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            items = args
        except TypeError:
            # not iterable – return empty
            return control_args, nested_args

    # optional custom sets defined on the instance for control and custom keys
    control_keys = getattr(self, "CONTROL_ARGS", set())
    custom_keys = getattr(self, "CUSTOM_ARGS", set())

    for itm in items:
        # each item may be a key, or a key/value tuple/list
        if isinstance(itm, (list, tuple)):
            if len(itm) == 2:
                key, value = itm
            else:
                # skip malformed entries
                continue
        else:
            key, value = itm, None

        # normalize key to a string if needed
        key = str(key)

        # classify based on known sets
        if key in control_keys:
            control_args[key] = value
        elif key in custom_keys:
            # custom args are treated as nested
            nested_args[key] = value
        else:
            # default behaviour – treat as nested
            nested_args[key] = value

    return control_args, nested_args

