def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import json, os, sys

    # locate a plugin spec file; common names are .json or .yaml/.yml
    spec_file = None
    for fname in ("plugin.json", "spec.json", "plugin.yaml", "spec.yaml", "plugin.yml", "spec.yml"):
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_file = path
            break

    if not spec_file:
        # nothing to load – return an empty dict but keep consistent API
        return {}

    # load the spec data – try JSON first, then YAML if available
    data = None
    try:
        if spec_file.endswith(".json"):
            with open(spec_file, "r", encoding="utf-8") as f:
                data = json.load(f)
        else:
            try:
                import yaml  # type: ignore
            except Exception:
                # yaml not available, cannot parse non‑JSON spec
                raise RuntimeError("YAML spec found but pyyaml is not installed")
            with open(spec_file, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
    except Exception as exc:  # pragma: no cover
        # If any error happens while reading or parsing, raise a clear error
        raise RuntimeError(f"Failed to load plugin spec from {spec_file!r}: {exc}") from exc

    if data is None or not isinstance(data, dict):
        return {}

    # flatten nested dicts – dotted keys
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    flat = _flatten(data)
    return flat

